  "item": "R1",
  "scores": {"U": 3, "A": 2, "C": 3, "V": 2},
  "confidences": {"U": 0.7, "A": 0.7, "C": 0.7, "V": 0.7},
  "rationales": {
    "U": "证据片段：'guide users throughout the interaction process quickly and effectively' – 解释：该描述整体可理解，但'quickly and effectively'缺乏具体定义，可能影响不同利益相关者的一致理解。",
    "A": "证据片段：'quickly and effectively' – 解释：这些术语主观且未指定标准，例如'quickly'可能指时间或步骤数，导致歧义。",
    "C": "证据片段：'avoid cognitive overloads caused by information overflow' – 解释：需求正确表达了避免认知过载的意图，但未说明具体设计方法或约束，可能不够精确。",
    "V": "证据片段：'guide users quickly and effectively' – 解释：缺乏可量化指标，如时间限制或成功率，难以验证需求是否被满足。"
  },
  "suggestions": {
    "U": "改写为：'系统必须在用户交互过程中提供清晰的引导，确保引导步骤易于跟随且反馈及时。'",
    "A": "改写为：'系统引导用户时，应定义'快速'为每一步引导响应时间不超过3秒，'有效'为用户能正确完成任务的比率超过95%。'",
    "C": "改写为：'系统设计应通过限制每次显示的信息量和使用渐进式披露来避免认知过载。'",
    "V": "改写为：'系统引导用户时，应满足：引导响应时间中位数不超过2秒，任务完成率不低于90%。'"
  },
  "issues": [
    {"type": "U", "evidence": "guide users throughout the interaction process quickly and effectively", "rewrite": "系统必须在交互过程中提供引导，引导步骤应清晰且反馈在2秒内。"},
    {"type": "A", "evidence": "quickly and effectively", "rewrite": "定义'快速'为引导响应时间≤3秒，'有效'为用户任务成功率≥95%。"},
    {"type": "C", "evidence": "avoid cognitive overloads caused by information overflow", "rewrite": "系统设计应限制同时显示的信息项不超过5个，并使用分步引导。"},
    {"type": "V", "evidence": "guide users quickly and effectively", "rewrite": "系统应测量引导响应时间（目标≤3秒）和用户任务完成率（目标≥95%）。"}
  ]
}

{
  "item": "R1",
  "scores": {"U": 2, "A": 2, "C": 3, "V": 1},
  "confidences": {"U": 0.9, "A": 0.95, "C": 0.8, "V": 0.95},
  "rationales": {"U":"'guide users throughout the interaction process quickly and effectively' is vague and lacks concrete behavioral or temporal criteria; 'quickly' is subjective and context-dependent, impairing understandability for non-native speakers or domain novices", "A":"'quickly and effectively' and 'cognitive overloads caused by information overflow' are inherently ambiguous: no definition of 'quickly' (e.g., <2s response), no metric for 'effectively', and 'information overflow' has no operational threshold (e.g., max 5 UI elements per view)", "C":"The requirement expresses a design intent rather than a verifiable system property; it does not contradict known domain facts, so correctness is moderately defensible, but conflates UX principle with functional specification", "V":"No testable condition is provided — e.g., no measurable criterion for 'avoid cognitive overloads' (e.g., task success rate ≥95%, or average fixation count ≤3 per screen in eye-tracking study), nor for 'guide... quickly' (e.g., system provides next-step hint within 800ms of user idle state)"}, 
  "suggestions": {"U":"Replace with atomic, user-action–triggered statements specifying observable behavior", "A":"Define all qualitative terms via measurable thresholds or normative references (e.g., ISO 9241-210)", "C":"Reframe as a system behavior constraint, not a design aspiration", "V":"Specify pass/fail criteria using objective, instrumentable metrics"},
  "issues": [
    {"type":"U","evidence":"The system must guide users throughout the interaction process quickly and effectively","rewrite":"For each user-initiated step in a defined workflow (e.g., 'submit form'), the system shall display a single contextual guidance element (e.g., tooltip or inline hint) within 800 ms of the triggering action."},
    {"type":"A","evidence":"avoid cognitive overloads caused by information overflow","rewrite":"No screen shall display more than 7±2 distinct interactive elements or textual information units (per Miller’s Law), and all screens shall comply with WCAG 2.1 Success Criterion 1.4.8 (Visual Presentation)."},
    {"type":"V","evidence":"The system must guide users throughout the interaction process quickly and effectively and it has to be designed to avoid cognitive overloads caused by information overflow.","rewrite":"In usability testing with 15 representative users, ≥90% shall complete the primary task flow without requesting assistance or navigating backward more than once, and eye-tracking data shall show average fixation count ≤5 per screen."}
  ]
}
